import{_ as t,o as d,c as a,ag as o}from"./chunks/framework.C5oN-8Wt.js";const u=JSON.parse('{"title":"噪声源","description":"","frontmatter":{},"headers":[],"relativePath":"v0.2.0-alpha/modules/noise_source/index.md","filePath":"v0.2.0-alpha/modules/noise_source/index.md"}'),r={name:"v0.2.0-alpha/modules/noise_source/index.md"};function i(l,e,c,n,h,s){return d(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="噪声源" tabindex="-1">噪声源 <a class="header-anchor" href="#噪声源" aria-label="Permalink to &quot;噪声源&quot;">​</a></h1><p>适用：v0.2.0-alpha · GNU Radio 3.10.12.0<br> 模块类型：<code>noise_source</code> · 模块定义版本：2</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>生成实数随机序列，用于给信号加入扰动、观察滤波效果或比较不同分布的统计特征。噪声没有固定周期，单次波形不能代表它的总体分布。</p><h2 id="典型接线" tabindex="-1">典型接线 <a class="header-anchor" href="#典型接线" aria-label="Permalink to &quot;典型接线&quot;">​</a></h2><p><code>信号源.out → 加法器.in1</code>，<code>噪声源.out → 加法器.in2</code>，再将加法器输出接到滤波器。两路进入同一个运算节点时须使用相同的采样率。</p><p>下表为内置默认参数下的端口。带路数、元素类型或 vlen 的模块会随参数改变流端口。</p><table tabindex="0"><thead><tr><th>方向</th><th>端口</th><th>数据类型</th><th>单位 / 形状</th></tr></thead><tbody><tr><td>输出</td><td><code>out</code>（输出）</td><td><code>numeric_f64</code></td><td>归一化幅度；vlen=1</td></tr></tbody></table><h2 id="参数怎么用" tabindex="-1">参数怎么用 <a class="header-anchor" href="#参数怎么用" aria-label="Permalink to &quot;参数怎么用&quot;">​</a></h2><p>幅度控制随机量的尺度，分布决定它的统计形状。比较分布时，应同时观察波形和统计器的直方图，并使用足够长的统计窗口。</p><p>固定种子适合重复对照；系统时间种子适合每次重新生成序列。噪声幅度不是某路信号的信噪比；信噪比还取决于信号功率和测量带宽。</p><p>内置默认值如下；本机设置可为<strong>新实例</strong>指定其他默认值，打开已有工程保留工程参数。</p><table tabindex="0"><thead><tr><th>参数</th><th>内置默认值</th><th>取值与约束</th><th>修改时机</th></tr></thead><tbody><tr><td>采样率 (Hz)<br><code>sample_rate_hz</code></td><td><code>4096</code></td><td>范围 1 至 1000000；Master 支持 1–1000000 Hz，可输入小数；下限保证单个采样周期不超过 1 秒。</td><td>重新准备</td></tr><tr><td>噪声幅度<br><code>amplitude</code></td><td><code>0</code></td><td>范围 -3.4028234663852886e+38 至 3.4028234663852886e+38</td><td>可在线应用</td></tr><tr><td>噪声分布<br><code>distribution</code></td><td><code>gaussian</code></td><td>高斯 (<code>gaussian</code>)；均匀 (<code>uniform</code>)；拉普拉斯 (<code>laplacian</code>)；脉冲 (<code>impulse</code>)</td><td>可在线应用</td></tr><tr><td>种子模式<br><code>seed_mode</code></td><td><code>fixed</code></td><td>固定 (<code>fixed</code>)；系统时间 (<code>system_time</code>)</td><td>重新准备</td></tr><tr><td>固定种子<br><code>seed</code></td><td><code>0</code></td><td>范围 0 至 2147483646</td><td>重新准备</td></tr></tbody></table><h2 id="在线修改与重新准备" tabindex="-1">在线修改与重新准备 <a class="header-anchor" href="#在线修改与重新准备" aria-label="Permalink to &quot;在线修改与重新准备&quot;">​</a></h2><p>运行中可在线应用以下字段组；同组字段一起提交：</p><ul><li><code>amplitude</code></li><li><code>distribution</code></li></ul><p>其余计算字段需停止并重新准备。在线应用以该节点实际回执为准；编辑草稿本身不会改变已运行的图，旧缓存仍可能包含修改前的数据。</p><p>在线改变噪声统计设置后，只影响后续生成的数据；旧缓存与统计窗口可能仍包含修改前的样本。需要从同一随机起点对照时，保持固定种子并停止、重新准备和运行；编辑种子不会回退运行中的随机序列。</p><h2 id="下载与观察" tabindex="-1">下载与观察 <a class="header-anchor" href="#下载与观察" aria-label="Permalink to &quot;下载与观察&quot;">​</a></h2><h3 id="实数信号、分支运算与三种选频滤波" tabindex="-1">实数信号、分支运算与三种选频滤波 <a class="header-anchor" href="#实数信号、分支运算与三种选频滤波" aria-label="Permalink to &quot;实数信号、分支运算与三种选频滤波&quot;">​</a></h3><p><a href="../../../downloads/v0.2.0-alpha/real-processing.cnsproj" download>下载 real-processing.cnsproj</a></p><p>来源：PC 本地 GNU Radio 仿真。下载后打开工程，按 F5 运行；本次核验每例参考源运行 2048 item，工程不保存样本。</p><p>实数信号、分支运算与三种选频滤波</p><ul><li>64 Hz 与 768 Hz 混合信号分支进入低通、高通、带通；比较增益、相乘、8 点延时与两抽头 FIR。</li></ul><p>实数处理示例将噪声与两个正弦分量相加。观察加法器波形的扰动，再比较低通输出和输入的频谱。可另插入统计器绑定噪声输出，查看分布随样本累计形成的形状。这是软件噪声仿真。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>为什么每次查看的波形都不一样？</strong> 连续运行会继续产生新样本；固定种子用于重复启动时的序列对照，不会让同一次运行停在同一段。</p><p><strong>噪声幅度很小仍有频谱起伏？</strong> 有限样本的随机频谱本来会波动，先比较相同窗口和显示范围。</p><h2 id="递进实验" tabindex="-1">递进实验 <a class="header-anchor" href="#递进实验" aria-label="Permalink to &quot;递进实验&quot;">​</a></h2><ul><li><a href="./../../learn/05-noise/">05 信号混入噪声</a></li><li><a href="./../../learn/06-filter/">06 滤波保留了什么</a></li></ul>',30)])])}const b=t(r,[["render",i]]);export{u as __pageData,b as default};
